:root {
  --bg: #0f1420;
  --surface: #1a2233;
  --surface-2: #232d42;
  --border: #2e3a54;
  --text: #e6ebf5;
  --muted: #93a0bd;
  --accent: #5b8cff;
  --accent-2: #3a6bf0;
  --danger: #ff6b7a;
  --star: #ffcb45;
  --radius: 12px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 22px;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand h1 { font-size: 20px; margin: 0; }
.logo { font-size: 24px; }

.search { flex: 1; max-width: 520px; }
.search input {
  width: 100%;
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
}
.search input:focus { outline: none; border-color: var(--accent); }

.btn {
  padding: 10px 16px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14px;
  cursor: pointer;
  transition: background .15s, border-color .15s;
}
.btn:hover { background: #2b3752; }
.btn.primary { background: var(--accent-2); border-color: var(--accent-2); color: #fff; }
.btn.primary:hover { background: var(--accent); }

.layout { display: flex; min-height: calc(100vh - 61px); }

.sidebar {
  width: 240px;
  flex-shrink: 0;
  padding: 20px 16px;
  border-right: 1px solid var(--border);
  background: var(--surface);
}
.filters { display: flex; flex-direction: column; gap: 4px; margin-bottom: 24px; }
.filter {
  text-align: left;
  padding: 9px 12px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--muted);
  font-size: 14px;
  cursor: pointer;
}
.filter:hover { background: var(--surface-2); color: var(--text); }
.filter.active { background: var(--surface-2); color: var(--text); font-weight: 600; }

.side-title { font-size: 12px; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); margin: 0 0 10px 4px; }
.tag-list { display: flex; flex-wrap: wrap; gap: 6px; }
.tag-list .chip { cursor: pointer; }
.tag-list .chip.active { background: var(--accent-2); border-color: var(--accent-2); color: #fff; }

.content { flex: 1; padding: 24px; }

.active-tag-bar { margin-bottom: 16px; color: var(--muted); display: flex; align-items: center; gap: 8px; }
.link-btn { background: none; border: none; color: var(--accent); cursor: pointer; font-size: 14px; padding: 0; }

.chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  color: var(--muted);
  font-size: 12px;
}
.chip .count { opacity: .6; }

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: border-color .15s, transform .1s;
}
.card:hover { border-color: var(--accent); }

.card-head { display: flex; align-items: flex-start; gap: 10px; }
.favicon { width: 20px; height: 20px; border-radius: 4px; flex-shrink: 0; margin-top: 2px; background: var(--surface-2); }
.card-title { font-size: 16px; font-weight: 600; margin: 0; flex: 1; word-break: break-word; }
.card-title a { color: var(--text); text-decoration: none; }
.card-title a:hover { color: var(--accent); }
.star-btn { background: none; border: none; cursor: pointer; font-size: 18px; color: #556; padding: 0; line-height: 1; }
.star-btn.on { color: var(--star); }

.card-url { font-size: 12px; color: var(--muted); word-break: break-all; }
.card-desc { font-size: 14px; color: #c3cbe0; }
.card-tags { display: flex; flex-wrap: wrap; gap: 5px; }
.card-tags .chip { cursor: pointer; }

.card-actions { display: flex; gap: 12px; margin-top: 4px; }
.card-actions button { background: none; border: none; color: var(--muted); cursor: pointer; font-size: 13px; padding: 0; }
.card-actions button:hover { color: var(--text); }
.card-actions .del:hover { color: var(--danger); }

.empty { text-align: center; color: var(--muted); padding: 80px 20px; display: flex; flex-direction: column; align-items: center; gap: 16px; }

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.55);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 50;
  padding: 20px;
}
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 460px;
}
.modal h2 { margin: 0 0 18px; }
.modal form { display: flex; flex-direction: column; gap: 14px; }
.modal label { display: flex; flex-direction: column; gap: 6px; font-size: 13px; color: var(--muted); }
.modal input[type=text], .modal textarea {
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
}
.modal input:focus, .modal textarea:focus { outline: none; border-color: var(--accent); }
.modal .checkbox { flex-direction: row; align-items: center; gap: 8px; color: var(--text); }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 6px; }
.form-error { color: var(--danger); font-size: 13px; }

@media (max-width: 700px) {
  .sidebar { display: none; }
  .topbar { flex-wrap: wrap; }
}

